svg.script:
// Initialize all animations
document.addEventListener('DOMContentLoaded', function() {
  // Force reflow to trigger CSS animations
  document.querySelectorAll('.node-group, .service-node, .docker-step, .security-box').forEach(function(el, i) {
    el.style.animationPlayState = 'running';
  });
});

// Hover highlight connected elements
const connections = {
  'layer-client': ['layer-compiler'],
  'layer-compiler': ['layer-services', 'layer-docker'],
  'layer-services': ['layer-docker'],
  'layer-docker': ['layer-compiler', 'layer-client']
};

document.querySelectorAll('[id^="layer-"]').forEach(function(layer) {
  layer.addEventListener('mouseenter', function() {
    const connected = connections[this.id] || [];
    connected.forEach(function(id) {
      const el = document.getElementById(id);
      if (el) el.style.filter = 'url(#glow)';
    });
  });
  layer.addEventListener('mouseleave', function() {
    const connected = connections[this.id] || [];
    connected.forEach(function(id) {
      const el = document.getElementById(id);
      if (el) el.style.filter = '';
    });
  });
});

// Click to focus on a section
document.querySelectorAll('.docker-step').forEach(function(step, i) {
  step.style.cursor = 'pointer';
  step.addEventListener('click', function() {
    // Pulse the clicked step
    this.querySelector('rect').animate([
      { strokeWidth: 2 },
      { strokeWidth: 5 },
      { strokeWidth: 2 }
    ], { duration: 600, easing: 'ease-out' });

    // Show tooltip
    showTooltip(this, i + 1);
  });
});

function showTooltip(element, stepNum) {
  const existing = document.getElementById('step-tooltip');
  if (existing) existing.remove();

  const tooltip = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  tooltip.id = 'step-tooltip';
  tooltip.innerHTML = `
    <rect x="0" y="0" width="200" height="60" rx="8" fill="#1e293b" filter="url(#shadow)"/>
    <text x="100" y="22" text-anchor="middle" font-family="system-ui" font-size="12" font-weight="600" fill="white">Step ${stepNum}</text>
    <text x="100" y="42" text-anchor="middle" font-family="system-ui" font-size="10" fill="#94a3b8">Click again to dismiss</text>
  `;
  const bbox = element.getBBox();
  tooltip.setAttribute('transform', `translate(${bbox.x + bbox.width/2 - 100}, ${bbox.y - 70})`);
  element.parentNode.appendChild(tooltip);

  setTimeout(() => tooltip.remove(), 3000);
  tooltip.addEventListener('click', () => tooltip.remove());
}
